//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry after `retry_number` failed attempts.
    pub fn delay_for_retry(&self, retry_number: u32) -> u64 {
        let exponent = retry_number.saturating_sub(1).min(63);
        self.base_delay_ms
            .saturating_mul(1u64 << exponent)
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delays_grow_exponentially_and_saturate() {
        let config = RetryConfig {
            max_attempts: 8,
            base_delay_ms: 100,
            max_delay_ms: 250,
        };

        assert_eq!(config.delay_for_retry(1), 100);
        assert_eq!(config.delay_for_retry(2), 200);
        assert_eq!(config.delay_for_retry(3), 250);
        assert_eq!(config.delay_for_retry(4), 250);
    }
}

